UniqueFd::UniqueFd(UniqueFd &&other) noexcept
{
    fd_ = other.fd_;
    other.fd_ = -1;
    if (fd_ >= 0) {
        // The fd's fdsan owner is still the source object's tag after the move;
        // rebind it to this object so a later close matches the declared owner.
        fdsan_exchange_owner_tag(fd_, other.Tag(), Tag());
    }
}

int UniqueFd::RemoveTag()
{
    if (fd_ < 0) {
        return -1;
    }
    fdsan_exchange_owner_tag(fd_, Tag(), 0);
    int fd = fd_;
    fd_ = -1;
    return fd;
}

int32_t DeviceConnectionForOutput::AddClientConnection(
    uint32_t clientId, int64_t deviceHandle, std::shared_ptr<MidiSharedRing> &buffer)
{
    std::lock_guard<std::mutex> lock(clientsMutex_);
    // dup a private copy for the client. The original stays owned (tagged) by this
    // object; the dup shares the same underlying file but has no owner tag, so the
    // receiving side may close it with a plain close().
    int fd = dup(notifyEventFd_.Get());
    CHECK_AND_RETURN_RET(fd >= 0, OH_MIDI_STATUS_SYSTEM_ERROR);
    (void)notifyEventFd_.RemoveTag();
    auto clientConnection = std::make_shared<ClientConnectionInServer>(clientId, deviceHandle, GetInfo().portIndex);

void UniqueFd::Reset(int fd)
{
    if (fd_ >= 0) {
        fdsan_close_with_tag(fd_, Tag());
        fd_ = -1;
    }
    if (fd >= 0) {
        fd_ = fd;
        // Bind this object's owner tag to the newly adopted fd immediately,
        // restoring the fd's owner from the default 0 to Tag(), so that a later
        // fdsan_close_with_tag(fd, Tag()) matches the fd's declared owner.
        fdsan_exchange_owner_tag(fd_, 0, Tag());
    }
}

